class Solution {
    private boolean isPrime(int value){
        if(value<2)return false;
        for(int divisor=2;divisor<=value/divisor;divisor++)if(value%divisor==0)return false;
        return true;
    }
    public int diagonalPrime(int[][] nums){
        int answer=0,n=nums.length;
        for(int i=0;i<n;i++){
            if(isPrime(nums[i][i]))answer=Math.max(answer,nums[i][i]);
            if(isPrime(nums[i][n-1-i]))answer=Math.max(answer,nums[i][n-1-i]);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    private fun isPrime(value:Int):Boolean{
        if(value<2)return false;
        var divisor=2;
        while(divisor<=value/divisor){
            if(value%divisor==0)return false;
            divisor++
        };
        return true
    }
    fun diagonalPrime(nums:Array<IntArray>):Int{
        var answer=0;
        val n=nums.size;
        for(i in 0 until n){
            if(isPrime(nums[i][i]))answer=maxOf(answer,nums[i][i]);
            if(isPrime(nums[i][n-1-i]))answer=maxOf(answer,nums[i][n-1-i])
        };
        return answer
    }
}

